package ui

// AdminAuroraCSS defines the "Aurora" admin visual theme mode's chrome
// palette (warm paper + ink-navy, hairline rules, square corners),
// restyling the shared, mode-agnostic sidebar/topbar/
// card/button/input markup the same way AdminNovaCSS, AdminShadcnCSS, and
// AdminWorkbenchCSS do (ADR-0041), reusing the shared semantic token names
// from AdminCSS (ADR-0053). Unlike those three, Aurora's *dashboard body* is
// not restyled here - it is its own Tailwind-authored markup (ADR-0339),
// kept in the separate, prefixed aurora.CSSText stylesheet. This file only
// covers the shell chrome, so the "aurora" family re-skins the whole shell
// the same way every other family does. See
// docs/architecture/0339-tailwind-admin-visual-family.md.
const AdminAuroraCSS = `html[data-ui-theme="aurora"]{--bg:#f6f4ee;--surface:#fbfaf6;--surface-raised:#fffefb;--surface-hover:#eeebe1;--bg-subtle:#efece3;--ink:#1c1a16;--ink-secondary:#4a463d;--muted:#8a8373;--line:#dcd6c6;--line-light:#c9c2ac;--brand:#17223f;--brand-hover:#263258;--brand-light:#1c2a4d;--brand-subtle:#eceef4;--brand-glow:rgba(23,34,63,.14);--brand-ink:#f6f4ee;--green:#3f6b3a;--green-subtle:#eef3ec;--red:#9a3b2d;--red-subtle:#f7ece9;--amber:#92661f;--radius-xs:0px;--radius-sm:2px;--radius-md:2px;--radius-lg:3px;--radius-xl:3px;--shadow-xs:none;--shadow-sm:none;--shadow-md:none;--shadow-lg:none;--card-highlight:none}html[data-ui-theme="aurora"][data-theme="dark"]{--bg:#15130f;--surface:#1c1a15;--surface-raised:#211f19;--surface-hover:#272419;--bg-subtle:#1c1a15;--ink:#ece7da;--ink-secondary:#c3bcab;--muted:#8d8573;--line:#352f22;--line-light:#453e2c;--brand:#c9d2ea;--brand-hover:#e3e8f5;--brand-light:#c9d2ea;--brand-subtle:#20283d;--brand-glow:rgba(201,210,234,.14);--brand-ink:#15192a;--green:#8fb787;--green-subtle:#1b2619;--red:#d79284;--red-subtle:#2a1714;--amber:#d3ab62;--shadow-xs:none;--shadow-sm:none;--shadow-md:none;--shadow-lg:none;--card-highlight:none}html[data-ui-theme="aurora"] body{background:var(--bg);color:var(--ink);font-feature-settings:"tnum" 1}html[data-ui-theme="aurora"] .studio-sidebar{background:var(--surface);border-right:1px solid var(--line);box-shadow:none}html[data-ui-theme="aurora"] .sidebar-header{border-bottom:1px solid var(--line);background:transparent}html[data-ui-theme="aurora"] .sidebar-bottom{border-top:1px solid var(--line);background:var(--surface)}html[data-ui-theme="aurora"] .studio-brand{color:var(--ink)}html[data-ui-theme="aurora"] .sidebar-section-label{color:var(--muted);text-transform:uppercase;letter-spacing:.09em}html[data-ui-theme="aurora"] .nav-item{color:var(--ink-secondary);border-radius:0;border-left:2px solid transparent}html[data-ui-theme="aurora"] .brand-text small{color:var(--muted)}html[data-ui-theme="aurora"] .brand-logo-mark{background:var(--brand);color:var(--brand-ink);border-radius:0;box-shadow:none}html[data-ui-theme="aurora"] .nav-item:hover{background:var(--bg-subtle);color:var(--ink);border-left-color:var(--line-light)}html[data-ui-theme="aurora"] .nav-item.is-active{background:transparent!important;color:var(--brand)!important;border-left-color:var(--brand)!important;box-shadow:none!important;font-weight:600!important}html[data-ui-theme="aurora"] .studio-topbar{background:var(--surface);border-bottom:1px solid var(--line);box-shadow:none}html[data-ui-theme="aurora"] .studio-card,html[data-ui-theme="aurora"] .dashboard-kpi,html[data-ui-theme="aurora"] .dashboard-card,html[data-ui-theme="aurora"] .collection-tile,html[data-ui-theme="aurora"] .tool-tile,html[data-ui-theme="aurora"] .meta-item,html[data-ui-theme="aurora"] .report-info-card{background:var(--surface);border-color:var(--line);box-shadow:none}html[data-ui-theme="aurora"] .studio-card,html[data-ui-theme="aurora"] .dashboard-kpi,html[data-ui-theme="aurora"] .dashboard-card,html[data-ui-theme="aurora"] .report-info-card{border-radius:0}html[data-ui-theme="aurora"] .studio-form button:not(.button-quiet):not(.button-secondary),html[data-ui-theme="aurora"] .button:not(.button-quiet):not(.button-secondary),html[data-ui-theme="aurora"] .studio-card button:not(.button-quiet):not(.button-secondary){border-radius:0;background:var(--brand);color:var(--brand-ink);box-shadow:none}html[data-ui-theme="aurora"] .studio-form button:not(.button-quiet):not(.button-secondary):hover,html[data-ui-theme="aurora"] .button:not(.button-quiet):not(.button-secondary):hover,html[data-ui-theme="aurora"] .studio-card button:not(.button-quiet):not(.button-secondary):hover{background:var(--brand-hover);color:var(--brand-ink);transform:none;box-shadow:none}html[data-ui-theme="aurora"] .button-quiet,html[data-ui-theme="aurora"] .button-secondary{border-radius:0;background:transparent!important;color:var(--ink)!important;border:1px solid var(--line)!important;box-shadow:none}html[data-ui-theme="aurora"] .button-quiet:hover,html[data-ui-theme="aurora"] .button-secondary:hover{background:var(--bg-subtle)!important;color:var(--brand)!important;border-color:var(--line-light)!important}html[data-ui-theme="aurora"] .studio-search{border-color:var(--line);border-radius:0;background:var(--surface);box-shadow:none}html[data-ui-theme="aurora"] .studio-search:hover{border-color:var(--line-light)}html[data-ui-theme="aurora"] .studio-search:focus-within{border-color:var(--brand);box-shadow:0 0 0 1px var(--brand)}html[data-ui-theme="aurora"] .theme-toggle-btn,html[data-ui-theme="aurora"] .studio-user{border-color:var(--line);border-radius:0;background:var(--surface);box-shadow:none}html[data-ui-theme="aurora"] input,html[data-ui-theme="aurora"] select,html[data-ui-theme="aurora"] textarea,html[data-ui-theme="aurora"] .studio-form input,html[data-ui-theme="aurora"] .studio-form select,html[data-ui-theme="aurora"] .studio-form textarea,html[data-ui-theme="aurora"] .studio-card input,html[data-ui-theme="aurora"] .studio-card select,html[data-ui-theme="aurora"] .studio-card textarea{border-radius:0;background:var(--surface);border-color:var(--line);color:var(--ink)}html[data-ui-theme="aurora"] input:focus,html[data-ui-theme="aurora"] select:focus,html[data-ui-theme="aurora"] textarea:focus,html[data-ui-theme="aurora"] .studio-form input:focus,html[data-ui-theme="aurora"] .studio-form select:focus,html[data-ui-theme="aurora"] .studio-form textarea:focus,html[data-ui-theme="aurora"] .studio-card input:focus,html[data-ui-theme="aurora"] .studio-card select:focus,html[data-ui-theme="aurora"] .studio-card textarea:focus{border-color:var(--brand);box-shadow:0 0 0 1px var(--brand)}html[data-ui-theme="aurora"] .studio-heading h1,html[data-ui-theme="aurora"] .dashboard-welcome h2{letter-spacing:-.01em;font-weight:700}html[data-ui-theme="aurora"] .studio-badge-status{border-color:var(--line);background:transparent;color:var(--ink-secondary);border-radius:0}html[data-ui-theme="aurora"] ::selection{background:var(--brand);color:var(--brand-ink)}html[data-ui-theme="aurora"] :focus-visible{outline:2px solid var(--brand);outline-offset:2px}`

// AdminAuroraDensityCSS mirrors AdminNovaDensityCSS's layout density rules,
// re-scoped to the Aurora mode's chrome.
const AdminAuroraDensityCSS = `html[data-ui-theme="aurora"] .studio-content{max-width:1600px}html[data-ui-theme="aurora"] .studio-card,html[data-ui-theme="aurora"] .dashboard-card{padding:20px 22px}html[data-ui-theme="aurora"] .studio-card h2,html[data-ui-theme="aurora"] .dashboard-card h2{font-size:1.02rem;letter-spacing:-.01em}html[data-ui-theme="aurora"] .studio-card th{background:var(--bg-subtle);color:var(--muted);font-size:.68rem;letter-spacing:.06em;text-transform:uppercase}html[data-ui-theme="aurora"] .studio-card td{font-size:.8rem}html[data-ui-theme="aurora"] .nav-item{min-height:38px;padding:9px 12px;font-size:.84rem;border-radius:var(--radius-md)}html[data-ui-theme="aurora"] .sidebar-section-label{margin:12px 10px 4px;font-size:.64rem;letter-spacing:.08em}html[data-ui-theme="aurora"] .studio-search{min-height:36px;height:36px;font-size:.84rem;border-radius:var(--radius-md)}html[data-ui-theme="aurora"] .button,html[data-ui-theme="aurora"] .studio-form button{min-height:38px;height:38px;padding:0 18px;font-size:.82rem;font-weight:600;border-radius:var(--radius-md)}html[data-ui-theme="aurora"] .button-quiet,html[data-ui-theme="aurora"] .button-secondary{min-height:38px;height:38px;padding:0 18px;font-size:.82rem;border-radius:var(--radius-md);color:var(--ink)!important}html[data-ui-theme="aurora"] .studio-alert{border:1px solid var(--red);border-radius:var(--radius-md)}html[data-ui-theme="aurora"] .studio-form label{font-size:.76rem;font-weight:600}html[data-ui-theme="aurora"] .studio-form input,html[data-ui-theme="aurora"] .studio-form select,html[data-ui-theme="aurora"] .studio-form textarea{font-size:.82rem;border-radius:var(--radius-md)}`

// AdminAuroraTypeCSS mirrors AdminNovaTypeCSS's font-family rules, re-scoped
// to the Aurora mode's chrome (the Tailwind-authored dashboard body sets its
// own font stack via utility classes, independent of this).
const AdminAuroraTypeCSS = `html[data-ui-theme="aurora"] body,html[data-ui-theme="aurora"] button,html[data-ui-theme="aurora"] input,html[data-ui-theme="aurora"] select,html[data-ui-theme="aurora"] textarea{font-family:"Inter",-apple-system,BlinkMacSystemFont,"Segoe UI Variable","Segoe UI",sans-serif!important;letter-spacing:-.011em}html[data-ui-theme="aurora"] code,html[data-ui-theme="aurora"] kbd,html[data-ui-theme="aurora"] pre{font-family:"JetBrains Mono","IBM Plex Mono","SFMono-Regular",Consolas,monospace!important}`

// AdminAuroraDashboardLayoutCSS toggles which dashboard markup is visible for
// the fifth admin visual family, "aurora" (ADR-0339), following the exact
// client-only display-toggle pattern AdminNovaDashboardLayoutCSS established
// for Nova (ADR-0335): every family's dashboard markup is always rendered
// into the page, and CSS alone decides which one is visible for the active
// html[data-ui-theme] value. Unlike the other four families, Aurora's own
// dashboard body is NOT re-skinned by AdminAuroraCSS above - it is authored
// directly with Tailwind utility classes and its own compiled, namespaced
// stylesheet (aurora.CSSText, concatenated into the shared admin stylesheet
// in admin_shell.go). See docs/architecture/0339-tailwind-admin-visual-family.md.
const AdminAuroraDashboardLayoutCSS = `html:not([data-ui-theme="aurora"]) .aurora-dashboard{display:none}
html[data-ui-theme="aurora"] .wb-dashboard{display:none}
html[data-ui-theme="aurora"] .nova-dashboard{display:none}`
